action_details.action_postfix:
// Physical nexus established - filing required
true result.ma_has_nexus xdef
"Massachusetts filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.ma_has_nexus xdef
"Massachusetts filing required: Economic nexus (exceeds $500,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Massachusetts state additions
0.0 /ma_additions xdef

// Common Massachusetts additions:
// - Federal bond interest
// - IRC 199A qualified business income deduction addback
// - Safe harbor lease deductions

result.ma_us_interest_income 0.0 ne
{
  ma_additions result.ma_us_interest_income add /ma_additions xdef
} if

ma_additions result.ma_state_additions xdef

// Calculate Massachusetts state subtractions
0.0 /ma_subtractions xdef

// Common Massachusetts subtractions:
// - Dividends from 15%+ owned subsidiaries (95% deduction)
// - Qualified capital gains on Massachusetts investments
// - Massachusetts NOL deduction

result.ma_municipal_interest 0.0 ne
{
  ma_subtractions result.ma_municipal_interest add /ma_subtractions xdef
} if

result.ma_qualified_dividend_deduction 0.0 ne
{
  ma_subtractions result.ma_qualified_dividend_deduction add /ma_subtractions xdef
} if

ma_subtractions result.ma_state_subtractions xdef

"Massachusetts additions: $" result.ma_state_additions cvs strconcat ", subtractions: $" strconcat result.ma_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Massachusetts taxable income // Federal taxable income apportioned to MA + additions - subtractions result.ma_apportioned_income result.ma_state_additions add result.ma_state_subtractions sub 0.0 max result.ma_taxable_income xdef
// Calculate Massachusetts tax using flat rate: 8.0% result.ma_taxable_income result.ma_corp_tax_rate mul /ma_tax_before_credits xdef
// Subtract Massachusetts state credits (EDIP, R&D, film credits, etc.) ma_tax_before_credits result.ma_state_credits sub 0.0 max result.ma_tax_liability xdef
// Calculate refund or amount owed result.ma_estimated_payments result.ma_tax_liability sub result.ma_refund_or_owed xdef
"Massachusetts taxable income: $" result.ma_taxable_income cvs strconcat job.audit_trail swap addto "Massachusetts tax liability (8.0%): $" result.ma_tax_liability cvs strconcat job.audit_trail swap addto
